#pragma once
// JSON-schema guided decoding.
//
// The sampler consults a compiled constraint and forces every emitted token to
// keep the generated byte stream a valid JSON prefix for the requested schema.
// The constraint is a byte-level pushdown automaton: JSON's grammar supplies the
// structural states (object key / colon / comma, array element, string escape,
// number grammar) and the schema supplies which value types, keys, enums,
// lengths and numeric ranges are allowed at each point.
//
// Two properties matter for the engine:
//
//  * the compiled schema is immutable and shared, while the run state lives in
//    sampler_state (one per sequence), so an `n`-choice request can share one
//    constraint without sharing progress;
//  * rejection is a logit mask, not a grammar rewrite, so penalties, logit_bias,
//    temperature and the rest of sample_token behave exactly as they do on the
//    unconstrained path.  EOS is masked off until the root value is complete,
//    so the model cannot stop on a truncated object.
//
// Supported keywords: type (including JSON Schema type arrays), properties,
// required, additionalProperties (bool or schema), minProperties/maxProperties,
// items, minItems/maxItems, minLength/maxLength, pattern, enum, const,
// minimum/maximum/exclusiveMinimum/exclusiveMaximum/multipleOf, anyOf/oneOf,
// allOf (merged), local $ref via #/$defs/... or #/definitions/..., and boolean
// schemas.  `format`, `patternProperties`, `prefixItems`, `if/then/else`,
// `not`, `dependentRequired` and remote $ref are ignored (permissive), which is
// the same trade llama.cpp's JSON-schema conversion makes for the unsupported
// keywords.
#include <memory>
#include <string>
#include <vector>

struct tokenizer;

namespace si {

struct guided_constraint;
class guided_state;

// Compile `schema_json` (a JSON Schema document; "" means the generic
// {"type":"object"} used by response_format={"type":"json_object"}).  `pieces`
// holds each vocabulary entry's raw byte piece; `eos_ids` are the terminal
// tokens (the sampler may emit one only once the root value is complete).
// Throws std::runtime_error on unparseable JSON or an impossible schema.
std::shared_ptr<const guided_constraint> make_guided_constraint(const std::string & schema_json,
                                                                std::vector<std::string> pieces,
                                                                std::vector<int> eos_ids);

// Same, using the loaded tokenizer.  The (large) token byte table is cached per
// tokenizer, so repeated requests pay only for the schema compile.
std::shared_ptr<const guided_constraint> make_guided_from_tokenizer(const tokenizer & tk,
                                                                    const std::string & schema_json);

// The generic JSON-object constraint (response_format: json_object).
std::shared_ptr<const guided_constraint> make_guided_json_object(const tokenizer & tk);

std::shared_ptr<guided_state> make_guided_state(const guided_constraint & gc);

// Mask disallowed tokens in `logits` (in place).  Returns false when the run
// state admits no token at all; the caller then disables the constraint for
// that sequence rather than emitting garbage.  A non-zero return is the number
// of allowed vocabulary entries (diagnostic only).
bool guided_apply(const guided_constraint & gc, guided_state & st, float * logits, int n_vocab);

// Advance the run state past an emitted token (EOS is a no-op: its bytes are
// not part of the JSON document).
void guided_commit(const guided_constraint & gc, guided_state & st, int token);

// True when the root JSON value is complete (EOS is already allowed).
bool guided_finished(const guided_constraint & gc, const guided_state & st);

} // namespace si
